def sgd_momentum(params, states, hyperparams):
for p, v in zip(params, states):
with torch.no_grad():

v[:] = hyperparams['momentum'] * v + p.grad p[:] -= hyperparams['lr'] * v p.grad.data.zero_() Let’s see how this works in practice.

